import {staticCollider,dynamicBox,solveTwoBoneIK,create3DEffects} from '../3d/index.js';
import {PIN_RACK} from './bowling-core.js';
export function createBowlingScene(r,{getSettings=()=>({})}={}){const {B,scene}=r,materials=new Map(),pins=new Map(),bodies=[],decor=[],spectators=[];let ball=null,ballAggregate=null,shot=null,clock=0,avatarPose=null,celebrate=0,preferredHand='right';scene.clearColor=new B.Color4(.07,.13,.2,1);const mat=(color)=>{if(materials.has(color))return materials.get(color);const m=new B.StandardMaterial('resort-'+color,scene);m.diffuseColor=B.Color3.FromHexString(color);m.specularColor=new B.Color3(.12,.12,.12);materials.set(color,m);return m;};
 function make(kind,name,options,color,position,parent=null,cast=true){const m=B.MeshBuilder[kind](name,options,scene);m.material=mat(color);m.position.set(...position);m.parent=parent;m.receiveShadows=true;if(cast)r.shadows?.addShadowCaster(m);return m;}
 function lane(x,live){const floor=make('CreateBox','maple-lane',{width:2.6,height:.2,depth:24},'#be9c69',[x,-.1,-2]);if(live)bodies.push(staticCollider(r,floor,{friction:.21,restitution:.08}));for(const side of [-1,1]){const gutter=make('CreateBox','gutter',{width:.5,height:.2,depth:24},'#263f55',[x+side*1.55,-.3,-2]);if(live)bodies.push(staticCollider(r,gutter,{friction:.15}));make('CreateBox','lane-divider',{width:.18,height:.28,depth:24},'#6d747c',[x+side*1.9,.04,-2]);}for(let i=0;i<9;i++)make('CreateBox','plank-seam',{width:.012,height:.002,depth:24},'#8c7658',[x-1.15+i*.28,.002,-2],null,false);make('CreateBox','foul-line',{width:2.6,height:.006,depth:.045},'#435e6a',[x,.009,5.9]);for(let i=-2;i<=2;i++){const arrow=make('CreateCylinder','aim-arrow',{diameter:.07,height:.005,tessellation:3},'#526a68',[x+i*.32,.012,3.8-Math.abs(i)*.18],null,false);}if(!live)for(const p of PIN_RACK)makePin('display-'+x+'-'+p.id,x+p.x,-p.z,false);}
 function pinMesh(name){const path=[new B.Vector3(0,-.55,0),new B.Vector3(.14,-.55,0),new B.Vector3(.19,-.37,0),new B.Vector3(.16,-.12,0),new B.Vector3(.08,.1,0),new B.Vector3(.065,.26,0),new B.Vector3(.14,.38,0),new B.Vector3(.12,.5,0),new B.Vector3(0,.56,0)],m=B.MeshBuilder.CreateLathe(name,{shape:path,tessellation:16,cap:B.Mesh.CAP_ALL},scene);m.material=mat('#ece7d8');m.receiveShadows=true;r.shadows?.addShadowCaster(m);return m;}
 function makePin(id,x,z,live=true){const m=pinMesh('pin-'+id);m.position.set(x,.57,z);const band=make('CreateTorus','pin-stripe',{diameter:.15,thickness:.035,tessellation:16},'#b85f76',[0,.23,0],m);if(live){const aggregate=new B.PhysicsAggregate(m,B.PhysicsShapeType.CONVEX_HULL,{mass:1.4,friction:.28,restitution:.32},scene);aggregate.body.setLinearDamping(.03);aggregate.body.setAngularDamping(.06);aggregate.shape.filterMembershipMask=4;aggregate.shape.filterCollideMask=1|2|4;pins.set(id,{mesh:m,aggregate,start:{x,z}});}else decor.push(m);return m;}
 lane(0,true);lane(-4.3,false);lane(4.3,false);const approach=make('CreateBox','approach-deck',{width:15,height:.25,depth:8},'#9d8b77',[0,-.12,13]);bodies.push(staticCollider(r,approach));const pit=make('CreateBox','pin-pit',{width:4,height:.3,depth:5},'#26364e',[0,-.4,-15]);bodies.push(staticCollider(r,pit));const back=make('CreateBox','backstop',{width:4,height:3,depth:.3},'#547b80',[0,1,-17]);bodies.push(staticCollider(r,back));
 for(const side of [-1,1]){make('CreateBox','palm-planter',{width:2,height:.8,depth:16},'#334f59',[side*7,.3,-1]);for(let j=0;j<5;j++){const x=side*7,z=7-j*4,trunk=make('CreateCylinder','palm-trunk',{diameterTop:.1,diameterBottom:.2,height:3.5,tessellation:7},'#8b7764',[x,2,z]);for(let k=0;k<6;k++){const leaf=make('CreateRibbon','palm-frond',{pathArray:[[new B.Vector3(0,0,0),new B.Vector3(.4,.25,.4),new B.Vector3(.8,.2,.9),new B.Vector3(1.1,-.25,1.3)],[new B.Vector3(.05,0,0),new B.Vector3(.7,.25,.15),new B.Vector3(1.15,.2,.6),new B.Vector3(1.1,-.25,1.3)]],sideOrientation:B.Mesh.DOUBLESIDE},'#588d79',[x,3.7,z]);leaf.rotation.y=k*Math.PI/3;}}}
 make('CreateBox','resort-horizon',{width:40,height:8,depth:.2},'#2b626f',[0,3,-20],null,false);for(let i=0;i<9;i++){const sail=make('CreateCylinder','sunlit-sail',{height:3+i%3,diameterTop:0,diameterBottom:2.5,tessellation:3},i%2?'#b39ba9':'#d0bd93',[-16+i*4,2.5,-19]);sail.rotation.z=.16;}for(const x of [-4.3,0,4.3]){make('CreateBox','pinsetter-sign',{width:3.3,height:1.1,depth:.18},'#416776',[x,2.6,-13.5]);for(let i=0;i<4;i++)make('CreateSphere','marquee-lamp',{diameter:.12,segments:6},'#e1c895',[x-1.2+i*.8,3.2,-13.4]);}
 const sweep=make('CreateBox','pinsetter-sweep',{width:3,height:.12,depth:.18},'#ca9c83',[0,2,-11.2]);const bench=make('CreateBox','spectator-bench',{width:3,height:.4,depth:5},'#626d83',[6.8,.5,11]);
 const batches=new Map();for(const m of [...scene.meshes])if(!m.physicsBody&&m!==sweep&&m.getTotalVertices()){m.computeWorldMatrix(true);const list=batches.get(m.material)||[];list.push(m);batches.set(m.material,list);}for(const parts of batches.values())for(const m of parts){m.setParent(null);m.computeWorldMatrix(true);}for(const [material,parts]of batches)if(parts.length>1){for(const p of parts)r.shadows?.removeShadowCaster(p);const merged=B.Mesh.MergeMeshes(parts,true,true,undefined,false,false);if(merged){merged.material=material;merged.receiveShadows=true;r.shadows?.addShadowCaster(merged);}}
 // Original joined sport avatar rig with lathed torso/head, shaped hair, clothing and face.
 const root=new B.TransformNode('resort-bowler',scene),rig={root,arms:{},parts:[]};root.position.set(0,0,7.7);root.rotation.y=Math.PI;
 function lathe(name,shape,color,pos,parent=root){return make('CreateLathe',name,{shape:shape.map(([x,y])=>new B.Vector3(x,y,0)),tessellation:18,cap:B.Mesh.CAP_ALL},color,pos,parent);}
 rig.shirt=lathe('sport-shirt',[[0,0],[.31,0],[.38,.45],[.34,.85],[.21,.94],[0,.94]],'#72bfb5',[0,.92,0]);lathe('sport-shorts',[[0,0],[.31,0],[.33,.4],[0,.4]],'#40536b',[0,.65,0]);rig.head=lathe('face-sculpt',[[0,-.32],[.19,-.29],[.29,-.1],[.3,.15],[.24,.32],[0,.38]],'#d8ad8d',[0,2.17,0]);rig.hair=lathe('hair-cap',[[0,0],[.29,0],[.31,.12],[.25,.3],[0,.34]],'#5f4c51',[0,2.28,-.01]);rig.hairParts=[];for(let i=0;i<5;i++)rig.hairParts.push(make('CreateSphere','hair-wave',{diameter:.2,segments:10},'#5f4c51',[-.22+i*.11,2.36,.18],root));for(const side of [-1,1]){make('CreateSphere','ear',{diameter:.16,segments:10},'#d8ad8d',[side*.3,2.14,0],root);make('CreateBox','eyebrow',{width:.13,height:.035,depth:.025},'#615058',[side*.11,2.25,.268],root);make('CreateSphere','eye-white',{diameter:.1,segments:10},'#eee5d6',[side*.11,2.17,.277],root);make('CreateSphere','eye-iris',{diameter:.046,segments:8},'#314d5b',[side*.11,2.17,.323],root);make('CreateCylinder','sock-leg',{height:.48,diameter:.2,tessellation:12},'#d4bc9f',[side*.17,.51,0],root);const shoe=make('CreateSphere','bowling-shoe',{diameter:.38,segments:12},side<0?'#b38187':'#79aab2',[side*.17,.18,.12],root);shoe.scaling.set(.8,.55,1.4);make('CreateBox','shoe-lace',{width:.18,height:.02,depth:.16},'#ead3a3',[side*.17,.29,.19],root);const upper=make('CreateCylinder','shirt-sleeve',{height:1,diameter:.21,tessellation:12},'#72bfb5',[0,0,0],root),lower=make('CreateCylinder','forearm',{height:1,diameter:.15,tessellation:12},'#d8ad8d',[0,0,0],root),hand=make('CreateSphere','hand',{diameter:.19,segments:12},'#d8ad8d',[0,0,0],root);rig.arms[side<0?'left':'right']={upper,lower,hand,side};}make('CreateSphere','nose',{diameter:.1,segments:10},'#ddb494',[0,2.1,.31],root);rig.mouth=make('CreateTorus','smile',{diameter:.14,thickness:.016,tessellation:16,arc:.5},'#875b66',[0,2.03,.273],root);rig.mouth.rotation.x=Math.PI/2;rig.accessory=make('CreateTorus','headband',{diameter:.6,thickness:.055,tessellation:24},'#d4c090',[0,2.32,0],root);rig.accessory.rotation.x=0;
 const heldBall=make('CreateSphere','held-ball',{diameter:.48,segments:20},'#6b72a1',[.38,1.05,.3],root);const effects=create3DEffects(r,{getPresentation:getSettings});let shotAge=0;
 function segment(m,a,b){const pa=new B.Vector3(a.x,a.y,a.z),pb=new B.Vector3(b.x,b.y,b.z),delta=pb.subtract(pa);m.position.copyFrom(pa.add(pb).scale(.5));m.scaling.y=delta.length();m.rotationQuaternion=B.Quaternion.FromUnitVectorsToRef(B.Vector3.Up(),delta.normalize(),m.rotationQuaternion||B.Quaternion.Identity());}
 function removeBall(){ballAggregate?.dispose();ballAggregate=null;ball?.dispose();ball=null;}
 function rack(standing,fresh=true){removeBall();shot=null;const positions=new Map();for(const [id,p]of pins){if(!fresh&&standing.includes(id))positions.set(id,{x:p.mesh.position.x,z:p.mesh.position.z});p.aggregate.dispose();p.mesh.dispose();}pins.clear();for(const id of standing){const p=positions.get(id)||{x:PIN_RACK[id].x,z:-PIN_RACK[id].z};makePin(id,p.x,p.z);}shotAge=0;celebrate=0;}
 function launch({aim=0,power=.65,curve=0,hand=preferredHand}={}){if(shot||!pins.size)return false;removeBall();ball=make('CreateSphere','rolling-ball',{diameter:.5,segments:20},'#7475ab',[Math.max(-1,Math.min(1,aim))*.92,.26,6]);for(let i=0;i<3;i++)make('CreateSphere','finger-hole',{diameter:.058,segments:8},'#273b51',[(i-1)*.065,.22,.07],ball);ballAggregate=new B.PhysicsAggregate(ball,B.PhysicsShapeType.SPHERE,{mass:6.5,friction:.2,restitution:.18},scene);ballAggregate.shape.filterMembershipMask=2;ballAggregate.shape.filterCollideMask=1|4;const speed=10+Math.max(.1,Math.min(1,power))*10,angle=Math.max(-1,Math.min(1,aim))*.025;ballAggregate.body.setLinearVelocity(new B.Vector3(Math.sin(angle)*speed,0,-Math.cos(angle)*speed));ballAggregate.body.setAngularVelocity(new B.Vector3(-speed/.25,curve*4,0));shot={power,curve,hand,gutter:false};shotAge=0;return true;}
 function fallen(){return [...pins].filter(([id,p])=>{p.mesh.computeWorldMatrix(true);const up=B.Vector3.TransformNormal(B.Vector3.Up(),p.mesh.getWorldMatrix()).normalize();return up.y<.7||p.mesh.position.y<.32||p.mesh.position.z<-13.2||Math.abs(p.mesh.position.x)>1.55;}).map(([id])=>id);}
 let aspect=0;return{rig,pins,get ball(){return ball;},get shot(){return shot;},rack,launch,fallen,setPose(pose){avatarPose=pose;},setHand(hand){preferredHand=hand==='left'?'left':'right';heldBall.position.x=preferredHand==='left'?-.38:.38;},setAvatar(options={}){rig.shirt.material=mat(options.shirt||'#72bfb5');for(const arm of Object.values(rig.arms))arm.upper.material=rig.shirt.material;rig.hair.scaling.y=options.hair==='crop'?.55:options.hair==='tall'?1.5:1;rig.hairParts.forEach(m=>m.setEnabled(options.hair!=='crop'));rig.accessory.setEnabled(options.accessory==='band');},cheer(){celebrate=2;},update(dt){clock+=dt;effects.update(dt);celebrate=Math.max(0,celebrate-dt);shotAge+=shot?dt:0;if(shot&&ball){if(!shot.gone&&(ball.position.y<-3||Math.abs(ball.position.x)>3||ball.position.z<-16)){shot.gone=true;ballAggregate.body.setMotionType(B.PhysicsMotionType.STATIC);ball.setEnabled(false);}if(Math.abs(ball.position.x)>1.35){shot.gutter=true;ballAggregate.shape.filterCollideMask=1;}if(!shot.gutter&&!shot.gone&&ball.position.z>-9)ballAggregate.body.applyForce(new B.Vector3(shot.curve*1.8,0,0),ball.position);}
 sweep.position.y=shot?2:1.7+Math.sin(clock*2)*.08;heldBall.setEnabled(!shot);root.rotation.y=celebrate?0:Math.PI;root.position.x=shot?0:Math.sin(clock*.8)*.025;for(const [name,arm]of Object.entries(rig.arms)){const a=avatarPose?.arms?.[name],origin={x:arm.side*.35,y:1.75,z:0},swing=shot&&name===shot.hand&&shotAge<.75?Math.sin(shotAge/.75*Math.PI):0,target=a?{x:Math.max(-.8,Math.min(.8,a.x*.42)),y:Math.max(.65,Math.min(2.65,1.75+a.y*.42)),z:Math.max(-.65,Math.min(.8,-a.z*.3))}:{x:arm.side*.46,y:celebrate?2.5:1.05+swing*.8,z:celebrate?.2:.2+swing*.5},ik=solveTwoBoneIK({root:origin,target,upperLength:.48,lowerLength:.49,pole:{x:arm.side,y:-.2,z:.3}});segment(arm.upper,origin,ik.elbow);segment(arm.lower,ik.elbow,ik.end);arm.hand.position.set(ik.end.x,ik.end.y,ik.end.z);}
 const ratio=r.canvas.clientWidth/Math.max(1,r.canvas.clientHeight);if(Math.abs(ratio-aspect)>.02){aspect=ratio;r.camera.radius=Math.min(55,Math.max(22,23/Math.max(.5,ratio)));r.camera.target.set(0,.7,0);}
 },resolved(){return !!shot&&(shotAge>3.2&&(shot.gone||ball?.position.z<-13)||shotAge>6.5);},dispose(){removeBall();for(const p of pins.values()){p.aggregate.dispose();p.mesh.dispose();}pins.clear();for(const b of bodies)b.dispose();effects.dispose();}};
}
